class Duck:
    def swim(self):
        return "Duck swimming"

    def quack(self):
        return "Quack quack!"

    def fly(self):
        return "Duck flying"

class RubberDuck:
    def swim(self):
        return "Rubber duck floating"

    def quack(self):
        return "Squeak squeak!"

    # No fly method - rubber ducks can't fly

class Bird:
    def swim(self):
        return "Bird swimming"

    def quack(self):
        return "Bird sound"

    def fly(self):
        return "Bird flying"

def make_it_swim(duck_like_object):
    """Duck typing in action - we don't care about the type, only the behavior"""
    return duck_like_object.swim()

def make_it_quack(duck_like_object):
    """Duck typing in action"""
    return duck_like_object.quack()

def make_it_fly(duck_like_object):
    """Duck typing in action - will fail for RubberDuck"""
    try:
        return duck_like_object.fly()
    except AttributeError:
        return f"{type(duck_like_object).__name__} cannot fly"

# Usage
duck = Duck()
rubber_duck = RubberDuck()
bird = Bird()

objects = [duck, rubber_duck, bird]

for obj in objects:
    print(f"{type(obj).__name__}:")
    print(f"  Swim: {make_it_swim(obj)}")
    print(f"  Quack: {make_it_quack(obj)}")
    print(f"  Fly: {make_it_fly(obj)}")
    print()
