class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __str__(self):
        return f"Point({self.x}, {self.y})"

    def __repr__(self):
        return f"Point({self.x}, {self.y})"

    def __add__(self, other):
        """Overload + operator"""
        if isinstance(other, Point):
            return Point(self.x + other.x, self.y + other.y)
        elif isinstance(other, (int, float)):
            return Point(self.x + other, self.y + other)
        else:
            raise TypeError(f"Can't add Point and {type(other).__name__}")

    def __sub__(self, other):
        """Overload - operator"""
        if isinstance(other, Point):
            return Point(self.x - other.x, self.y - other.y)
        elif isinstance(other, (int, float)):
            return Point(self.x - other, self.y - other)
        else:
            raise TypeError(f"Can't subtract {type(other).__name__} from Point")

    def __eq__(self, other):
        """Overload == operator"""
        if isinstance(other, Point):
            return self.x == other.x and self.y == other.y
        return False

    def __lt__(self, other):
        """Overload < operator (compare by distance from origin)"""
        if isinstance(other, Point):
            return (self.x**2 + self.y**2) < (other.x**2 + other.y**2)
        return NotImplemented

    def __len__(self):
        """Overload len() function (distance from origin)"""
        return int((self.x**2 + self.y**2)**0.5)

    def distance_to(self, other):
        """Calculate distance to another point"""
        if isinstance(other, Point):
            return ((self.x - other.x)**2 + (self.y - other.y)**2)**0.5
        raise TypeError("Argument must be a Point")

# Usage
p1 = Point(3, 4)
p2 = Point(1, 2)

print(f"p1: {p1}")
print(f"p2: {p2}")
print(f"p1 + p2: {p1 + p2}")
print(f"p1 - p2: {p1 - p2}")
print(f"p1 + 5: {p1 + 5}")
print(f"p1 == p2: {p1 == p2}")
print(f"p1 < p2: {p1 < p2}")
print(f"Length of p1: {len(p1)}")
print(f"Distance from p1 to p2: {p1.distance_to(p2):.2f}")
