from abc import ABC, abstractmethod

class PaymentMethod(ABC):
    def __init__(self, amount):
        self.amount = amount

    @abstractmethod
    def process_payment(self):
        pass

    @abstractmethod
    def get_payment_info(self):
        pass

    def validate_amount(self):
        return self.amount > 0

class CreditCard(PaymentMethod):
    def __init__(self, amount, card_number, expiry_date, cvv):
        super().__init__(amount)
        self.card_number = card_number
        self.expiry_date = expiry_date
        self.cvv = cvv

    def process_payment(self):
        if self.validate_amount() and self._validate_card():
            return f"Credit card payment of ${self.amount} processed"
        return "Payment failed"

    def get_payment_info(self):
        return f"Credit Card: ****{self.card_number[-4:]}"

    def _validate_card(self):
        # Simple validation - in real world, this would be more complex
        return (len(self.card_number) == 16 and 
                len(self.cvv) == 3 and 
                len(self.expiry_date) == 5)

class PayPal(PaymentMethod):
    def __init__(self, amount, email):
        super().__init__(amount)
        self.email = email

    def process_payment(self):
        if self.validate_amount() and self._validate_email():
            return f"PayPal payment of ${self.amount} processed"
        return "Payment failed"

    def get_payment_info(self):
        return f"PayPal: {self.email}"

    def _validate_email(self):
        return '@' in self.email and '.' in self.email

class BankTransfer(PaymentMethod):
    def __init__(self, amount, account_number, routing_number):
        super().__init__(amount)
        self.account_number = account_number
        self.routing_number = routing_number

    def process_payment(self):
        if self.validate_amount() and self._validate_account():
            return f"Bank transfer of ${self.amount} processed"
        return "Payment failed"

    def get_payment_info(self):
        return f"Bank Transfer: ****{self.account_number[-4:]}"

    def _validate_account(self):
        return len(self.account_number) >= 8 and len(self.routing_number) == 9

# Polymorphic payment processing
def process_payments(payment_methods):
    results = []
    for payment in payment_methods:
        info = payment.get_payment_info()
        result = payment.process_payment()
        results.append(f"{info} - {result}")
    return results

# Usage
payments = [
    CreditCard(100, "1234567890123456", "12/25", "123"),
    PayPal(50, "user@example.com"),
    BankTransfer(200, "12345678", "123456789")
]

results = process_payments(payments)
for result in results:
    print(result)
