class Calculator:
    def add(self, *args):
        """Simulate method overloading with variable arguments"""
        if len(args) == 1:
            if isinstance(args[0], (list, tuple)):
                return sum(args[0])
            else:
                return args[0]
        elif len(args) == 2:
            return args[0] + args[1]
        else:
            return sum(args)

    def multiply(self, *args):
        """Simulate method overloading with variable arguments"""
        if len(args) == 1:
            if isinstance(args[0], (list, tuple)):
                result = 1
                for num in args[0]:
                    result *= num
                return result
            else:
                return args[0]
        elif len(args) == 2:
            return args[0] * args[1]
        else:
            result = 1
            for num in args:
                result *= num
            return result

    def power(self, base, exponent=None):
        """Simulate method overloading with default parameters"""
        if exponent is None:
            return base ** 2  # Default to square
        return base ** exponent

# Usage
calc = Calculator()

print(f"add(5): {calc.add(5)}")
print(f"add(5, 3): {calc.add(5, 3)}")
print(f"add(1, 2, 3, 4, 5): {calc.add(1, 2, 3, 4, 5)}")
print(f"add([1, 2, 3, 4, 5]): {calc.add([1, 2, 3, 4, 5])}")

print(f"\nmultiply(5): {calc.multiply(5)}")
print(f"multiply(5, 3): {calc.multiply(5, 3)}")
print(f"multiply(1, 2, 3, 4, 5): {calc.multiply(1, 2, 3, 4, 5)}")
print(f"multiply([1, 2, 3, 4, 5]): {calc.multiply([1, 2, 3, 4, 5])}")

print(f"\npower(5): {calc.power(5)}")
print(f"power(5, 3): {calc.power(5, 3)}")
